import json
records=[json.loads(x) for x in lines]
actions=[]
for rec in records:
    msg=rec.get('message',{})
    if msg.get('role')=='assistant':
        for c in msg.get('content',[]):
            if c.get('type')=='text' and c.get('text','').startswith('{"action"'):
                try:
                    obj=json.loads(c['text']);
                    if obj.get('action')=='submit': actions.append((obj,rec['timestamp']))
                except: pass
[(len(a['grid']),sorted(set(len(r) for r in a['grid'])), [len(r) for r in a['grid']]) for a,_ in actions],len(actions)
